 // Payslip HowTo (visible content mirroring HowTo JSON-LD)
 'payslip.howto.title': 'Come simulare la busta paga del nuovo frontaliere',
 'payslip.howto.intro': 'Guida passo-passo per simulare la busta paga del nuovo frontaliere Svizzera-Italia 2026 con imposta alla fonte Ticino, deduzioni AVS/LPP e confronto netto CH vs IT.',
 'payslip.howto.step1.name': 'Inserisci lo stipendio lordo annuale in CHF',
 'payslip.howto.step1.text': 'Digita lo stipendio lordo annuale in franchi svizzeri (CHF) così come appare sul contratto di lavoro. Il simulatore calcola automaticamente il lordo mensile dividendo per 13 (tredicesima inclusa).',
 'payslip.howto.step2.name': 'Indica età, stato civile e figli a carico',
 'payslip.howto.step2.text': 'Seleziona età (determina l\'aliquota LPP), stato civile (barème A celibe o B coniugato) e numero di figli a carico. Ogni figlio riduce l\'imposta alla fonte di circa 1 punto percentuale.',
 'payslip.howto.step3.name': 'Scegli la zona di residenza (entro o oltre 20 km)',
 'payslip.howto.step3.text': 'Indica se risiedi entro 20 km dal confine svizzero oppure oltre. Con il Nuovo Accordo 2026 i nuovi frontalieri entro 20 km pagano l\'80% alla fonte in Svizzera e IRPEF in Italia con franchigia di €10.000, mentre oltre 20 km la trattenuta svizzera è al 100%.',
 'payslip.howto.step4.name': 'Verifica le deduzioni sociali svizzere',
 'payslip.howto.step4.text': 'Controlla il dettaglio delle trattenute obbligatorie: AVS/AI/IPG (5,3%), AD disoccupazione (1,1%), AINF infortuni non professionali, IJM malattia e LPP (2° pilastro, aliquota per fascia d\'età 25-65 anni).',
 'payslip.howto.step5.name': 'Visualizza la simulazione dell\'imposta alla fonte',
 'payslip.howto.step5.text': 'Consulta il calcolo dell\'imposta alla fonte applicata secondo il barème cantonale ticinese A/B/C/H 2026, con la percentuale e l\'importo in CHF su base mensile.',
 'payslip.howto.step6.name': 'Confronta il netto CHF con il netto in euro in Italia',
 'payslip.howto.step6.text': 'Confronta il netto svizzero con quello italiano considerando IRPEF e credito d\'imposta: questa è la cifra che effettivamente resta al nuovo frontaliere nel 2026.',
 'payslip.howto.step7.name': 'Esporta il cedolino in PDF',
 'payslip.howto.step7.text': 'Scarica il riepilogo della simulazione in PDF con tutte le trattenute AVS, AD, AINF, IJM, LPP e imposta alla fonte: utile per confrontarlo con la busta paga reale ricevuta dal datore di lavoro.',

 // Payslip FAQ (visible content mirroring FAQPage JSON-LD)
 'payslip.faq.title': 'Domande frequenti sulla busta paga del frontaliere',
 'payslip.faq.q1.q': 'Che cos\'è il Nuovo Accordo frontalieri 2026?',
 'payslip.faq.q1.a': 'Il Nuovo Accordo fiscale Italia-Svizzera (in vigore dal 2024 e pienamente applicato nel 2026) distingue tra "vecchi" e "nuovi" frontalieri. I nuovi frontalieri (assunti dal 17/07/2023) che risiedono entro 20 km dal confine pagano l\'80% dell\'imposta alla fonte in Svizzera e dichiarano il reddito in Italia con franchigia di €10.000 e credito d\'imposta. Oltre i 20 km, la trattenuta svizzera sale al 100%.',
 'payslip.faq.q2.q': 'Quando si è considerati "nuovo frontaliere"?',
 'payslip.faq.q2.a': 'Si è nuovo frontaliere se il contratto di lavoro svizzero è stato firmato a partire dal 17 luglio 2023. Chi era assunto prima di questa data resta "vecchio frontaliere" fino al 31 dicembre 2033 (periodo transitorio), con tassazione solo in Svizzera al 100% e ristorni ai comuni italiani di frontiera.',
 'payslip.faq.q3.q': 'Come si calcola l\'imposta alla fonte in Ticino nel 2026?',
 'payslip.faq.q3.a': 'L\'imposta alla fonte in Ticino è applicata dal datore di lavoro secondo il barème cantonale: A (celibe/nubile senza figli), B (coniugato/a unico reddito), C (coniugato/a doppio reddito) e H (famiglia monoparentale). L\'aliquota dipende dal reddito mensile lordo e varia da circa 2% (CHF 3.000/mese) a 16% (oltre CHF 15.000/mese). Ogni figlio a carico riduce l\'aliquota di circa 1 punto percentuale.',
 'payslip.faq.q4.q': 'Cosa cambia se vivo oltre 20 km dal confine svizzero?',
 'payslip.faq.q4.a': 'I nuovi frontalieri che risiedono oltre 20 km dal confine svizzero perdono lo status fiscale di frontaliere secondo il Nuovo Accordo: pagano il 100% dell\'imposta alla fonte in Svizzera (come i residenti senza ristorno) e dichiarano il reddito in Italia con credito d\'imposta pieno per evitare la doppia imposizione. La franchigia €10.000 non si applica in questo caso.',
 'payslip.faq.q5.q': 'I contributi AVS e LPP sono deducibili in Italia?',
 'payslip.faq.q5.a': 'Sì. I contributi previdenziali obbligatori AVS/AI/IPG (5,3%) e LPP (2° pilastro) trattenuti in Svizzera sono deducibili dal reddito imponibile IRPEF nella dichiarazione italiana dei nuovi frontalieri, riducendo di fatto la base imponibile italiana. Conserva il certificato di salario annuale svizzero (Lohnausweis) per il commercialista.',
 'payslip.faq.q6.q': 'Posso usare il simulatore anche se ho il Permesso B?',
 'payslip.faq.q6.a': 'Il simulatore di busta paga calcola le trattenute sociali (AVS, AD, AINF, IJM, LPP) e l\'imposta alla fonte ticinese: sono le stesse voci presenti sul cedolino di un residente con permesso B che lavora in Ticino. Tuttavia, con permesso B non si applica il regime speciale del frontaliere (credito d\'imposta italiano): il netto CHF è il tuo vero netto. Per un confronto fiscale G vs B usa il comparatore dedicato.',
 'payslip.faq.q7.q': 'L\'imposta alla fonte è definitiva o posso recuperare qualcosa con la TDR?',
 'payslip.faq.q7.a': 'L\'imposta alla fonte ticinese può essere rettificata tramite la TDR (Tariffa Doganale Ridotta) entro il 31 marzo dell\'anno successivo. Sono ammesse deduzioni per spese di trasporto (max CHF 3.200), pasti fuori casa, contributi 3° pilastro (max CHF 7.258 nel 2026), spese mediche e alimenti. Il rimborso viene accreditato direttamente sul conto bancario.',
 'payslip.faq.q8.q': 'Il simulatore include la tredicesima e gli assegni familiari?',
 'payslip.faq.q8.a': 'Lo stipendio lordo annuale inserito comprende già la tredicesima (si divide per 13 per il lordo mensile). Gli assegni familiari cantonali (circa CHF 200-300 al mese per figlio in Ticino) non sono invece inclusi nella simulazione perché non soggetti a trattenute sociali e imposta alla fonte: vanno sommati al netto calcolato.',

