 'salaryCompare.cantonAll': 'Svizzera (media nazionale)',
 'salaryCompare.cantonNetTitle': 'Netto stimato per Cantone (CH)',
 'salaryCompare.cantonNetDesc': 'Stima del netto svizzero se lo stesso profilo lavorasse in un altro cantone, basata sui livelli salariali regionali UST (Ufficio Federale di Statistica).',
 'salaryCompare.cantonNetDisclaimer': 'Attenzione: questa è una STIMA, non un calcolo fiscale ufficiale. Il lordo per cantone riflette il livello salariale medio regionale (dati UST); il netto usa l\'aliquota di carico fiscale reale del capoluogo di ciascun cantone (dati ufficiali ESTV, persona sola senza figli, anno fiscale 2024), quindi riflette le vere differenze di carico fiscale cantonale/comunale — ma non tiene conto della tua situazione personale specifica (stato civile, figli, deduzioni, comune esatto di residenza). Per una stima fiscale accurata, consulta il calcolatore ufficiale del tuo cantone di lavoro.',
 'salaryCompare.cantonNetColGross': 'Lordo stimato',
 'salaryCompare.cantonNetColNet': 'Netto stimato',
 'salaryCompare.cantonNetComuneNote': 'Cerchi una stima per il tuo comune di residenza in Italia?',
 'salaryCompare.cantonNetComuneLink': 'Usa la Mappa dei Comuni di Confine',
 'salaryCompare.salaryRange': 'Range salariale',
 'salaryCompare.median': 'Mediano',
 'salaryCompare.professions': 'Professioni',
 'salaryCompare.totalSectors': 'settori analizzati',
 'salaryCompare.totalProfessions': 'professioni analizzate',
 'salaryCompare.methodology': 'Metodologia e Fonti Dati',
 'salaryCompare.methodologyText1': 'I dati salariali presentati sono basati sulla Rilevazione svizzera della struttura dei salari (LSE) dell\'Ufficio federale di statistica (UST), integrati con dati SECO, portali di lavoro (jobs.ch, Michael Page) e stime di mercato 2024-2025. I salari svizzeri sono specificamente adattati per il Canton Ticino, che presenta mediamente retribuzioni del 10-15% inferiori alla media nazionale.',
 'salaryCompare.methodologyText2': 'Per l\'Italia, i dati sono tratti da ISTAT, Glassdoor e Indeed, con focus sulle regioni di frontiera (Lombardia, Piemonte, Liguria). I calcoli netti includono le deduzioni sociali svizzere (AVS/AI/IPG 5.3%, AD 1.1%, AINF 0.7%, IJM 0.8%, LPP media), l\'imposta alla fonte ticinese e per l\'Italia IRPEF 2026, addizionali regionali e contributi INPS.',
 'salaryCompare.methodologyText3': 'I range salariali (minimo-mediano-massimo) riflettono la variabilità legata a dimensione dell\'azienda, esperienza specifica, certificazioni e capacità negoziali. La parità di potere d\'acquisto (PPP) è calcolata con fattore 0.65, considerando il costo della vita significativamente più alto in Svizzera rispetto all\'Italia.',
 'salaryCompare.faqTitle': 'Domande Frequenti sugli Stipendi',
 'salaryCompare.faq1Q': 'Quali sono gli stipendi medi in Ticino nel 2026?',
 'salaryCompare.faq1A': 'Lo stipendio mediano in Ticino varia da CHF 48.000-55.000 per posizioni entry-level nel commercio/ristorazione fino a CHF 125.000-200.000+ per ruoli senior nella finanza, pharma e IT. Il Ticino ha i salari più bassi della Svizzera ma rimangono 2-3 volte superiori rispetto all\'Italia.',
 'salaryCompare.faq2Q': 'Quanto guadagna un informatico frontaliere in Svizzera?',
 'salaryCompare.faq2A': 'Un Software Developer frontaliere in Ticino guadagna mediamente CHF 72.000 lordi da junior (0-3 anni), CHF 95.000 da mid-level (3-7 anni) e CHF 125.000+ da senior (7+ anni). Al netto dell\'imposta alla fonte e dei contributi sociali, il netto junior è circa CHF 58.000 e il senior circa CHF 93.000.',
 'salaryCompare.faq3Q': 'Conviene fare il frontaliere dal punto di vista economico?',
 'salaryCompare.faq3A': 'Nella maggior parte dei settori, il frontaliere guadagna dal 100% al 200% in più rispetto a un equivalente lavoro in Italia, anche considerando i costi di trasporto e le tasse. Tuttavia, applicando la parità di potere d\'acquisto (PPP), il vantaggio si riduce al 30-80% poiché il costo della vita svizzero è molto più alto.',
 'salaryCompare.faq4Q': 'Come vengono tassati gli stipendi dei frontalieri?',
 'salaryCompare.faq4A': 'I frontalieri con permesso G pagano l\'imposta alla fonte nel Canton Ticino (dal 3% al 18% a seconda del reddito), più i contributi sociali svizzeri (AVS, AD, AINF, IJM, LPP). Con il Nuovo Accordo 2026, i nuovi frontalieri pagano anche l\'80% delle imposte in Svizzera e una quota in Italia con franchigia di €10.000.',
 'salaryCompare.faq5Q': 'Quali settori pagano di più in Ticino?',
 'salaryCompare.faq5A': 'I settori con le retribuzioni più alte in Ticino sono: Finanza & Banche (mediana senior CHF 145.000), Farmaceutico (CHF 135.000), Consulenza (CHF 150.000) e IT & Software (CHF 125.000). Ristorazione e Commercio offrono i salari più bassi (CHF 68.000-72.000 senior).',
