 'jobBoard.assisted.review.fit.lowTitle': "Il tuo profilo non copre un requisito indispensabile dell’annuncio",
 'jobBoard.assisted.review.fit.lowBody': "L’azienda potrebbe scartare la candidatura per questo. Puoi inviarla comunque: se il requisito lo soddisfi e dal CV non si vede, scrivilo nelle risposte qui sotto o chiedici una modifica.",
