 'jobBoard.assisted.review.fit.partialBodyEdit': "La candidatura parte comunque. Te lo diciamo prima dell’invio, così decidi tu: se li soddisfi, scrivilo nella lettera con «Modifica» oppure chiedici una nuova versione con «Chiedi modifiche».",
