 'jobBoard.assisted.review.lockedQuestion': "Si cambia nella domanda qui sopra.",
 'jobBoard.assisted.review.permitRule': "Nel CV mettiamo solo fatti: la tua nazionalità e il permesso che hai oggi, mai un «permesso da richiedere», perché il rilascio dipende dal contratto di lavoro e dal Cantone.",
