 'jobBoard.assisted.review.cvTitle': "Il CV che inviamo",
 'jobBoard.assisted.review.cvPdf': "Apri il CV adattato",
 'jobBoard.assisted.review.cvIntro': "Abbiamo riordinato il tuo CV per questo annuncio, con le parole che usa l’azienda: nessun dato nuovo, solo quello che c’è già nel tuo CV e quello che indichi in questa pagina. Controllalo: se preferisci, inviamo il tuo CV originale.",
 'jobBoard.assisted.review.cvPermitOmitted': "Il permesso G non compare nel CV: lo indichiamo solo accanto a una nazionalità dell’UE o dell’AELS presente nei tuoi dati, perché per i cittadini di altri Stati è legato a un solo datore di lavoro e a una zona di confine.",
 'jobBoard.assisted.review.cvPersonalDataNote': "Permesso, nazionalità e data di nascita che indichi in questa pagina compaiono solo nel CV adattato: il tuo CV originale riporta quello che c’è nel tuo file.",
 'jobBoard.assisted.review.cvPersonalDataNoteInplace': "Permesso, nazionalità e data di nascita che indichi in questa pagina compaiono solo nel CV adattato: il tuo CV originale e il file Word con le righe adattate riportano quello che c’è nel tuo file.",
 'jobBoard.assisted.review.cvAts': "Parole chiave dell’annuncio trovate: {before}% nel tuo CV, {after}% nel CV adattato.",
 'jobBoard.assisted.review.cvChooseTailored': "Invia il CV adattato",
 'jobBoard.assisted.review.cvChooseOriginal': "Invia il mio CV originale",
