 'jobBoard.assisted.review.cvInplaceNeedsCheck': "Il tuo file Word non è più tra le scelte: le righe che hai cambiato potrebbero spostarne l'impaginazione e qui non possiamo ricontare le pagine. Torna disponibile se rimetti le righe adattate; intanto puoi inviare il CV adattato o il tuo CV originale.",
 'jobBoard.assisted.review.wordCopyLetter': "Copia Word della lettera, da tenere e modificare",
 'jobBoard.assisted.review.wordCopyCv': "Copia Word del CV, da tenere e modificare",
 'jobBoard.assisted.review.wordCopyNote': "Le copie Word sono per te, da conservare e modificare: non sono mai i file inviati all’azienda.",
 'jobBoard.assisted.review.wordCopyNoPhoto': "La copia Word del CV non contiene la foto: se vuoi, la inserisci tu in Word.",
