 'renovation.deductible': 'Deducibile',
 'renovation.notDeductible': 'Non deducibile',
 'renovation.swissCategories': 'Categorie lavori (CH)',
 'renovation.availableBonuses': 'Bonus disponibili (IT)',
 'renovation.deductionInfo': 'Detrazione del {percent}% ripartita in {years} quote annuali di pari importo.',
 'renovation.updated2026': 'Aggiornato Legge di Bilancio 2026',
 'renovation.propertyType': 'Tipo di immobile',
 'renovation.primaCasa': 'Prima casa',
 'renovation.secondaCasa': 'Seconda casa',
 'renovation.secondaCasaNote': 'Per la seconda casa, il bonus ristrutturazione scende dal 50% al 36% con tetto massimo di €48.000 (Legge di Bilancio 2026).',
 'renovation.capienzaTitle': 'Importante per i frontalieri: capienza fiscale',
 'renovation.capienzaWarning': 'Le detrazioni per ristrutturazione riducono l\'IRPEF dovuta. Se sei frontaliere e il tuo reddito svizzero non è soggetto a IRPEF (vecchio accordo), puoi sfruttare il bonus solo se hai altre imposte italiane da compensare: redditi da affitto, IMU, rendite catastali o altri redditi dichiarati in Italia. Senza capienza fiscale, la detrazione resta inutilizzata.',
 'renovation.faqTitle': 'Domande frequenti — Frontalieri e bonus casa',
 'renovation.faq.frontaliereBonusAccess.q': 'Un frontaliere può usufruire dei bonus ristrutturazione italiani?',
 'renovation.faq.frontaliereBonusAccess.a': 'Sì, a condizione che abbia "capienza fiscale", ovvero imposte italiane (IRPEF) da cui detrarre il bonus. Le spese vanno inserite nel Quadro RP della dichiarazione dei redditi (Modello Redditi PF). Per i nuovi frontalieri (dal 2024) che dichiarano il reddito svizzero in Italia, la capienza è generalmente sufficiente. Per i vecchi frontalieri, serve avere altri redditi italiani tassabili.',
 'renovation.faq.capienzaFiscale.q': 'Cos\'è la capienza fiscale e perché è cruciale?',
 'renovation.faq.capienzaFiscale.a': 'La "capienza fiscale" è l\'ammontare di IRPEF lorda che devi pagare. Le detrazioni per ristrutturazione riducono direttamente questa imposta. Se la tua IRPEF lorda è zero (es. frontaliere vecchio accordo senza altri redditi italiani), non puoi beneficiare della detrazione. Fonti di capienza: redditi da locazione, rendite catastali, redditi da lavoro autonomo, altri redditi dichiarati in Italia.',
 'renovation.faq.quadroRP.q': 'Come si dichiarano le spese di ristrutturazione?',
 'renovation.faq.quadroRP.a': 'Le spese vanno inserite nel Quadro RP (Sezione III-A) del Modello Redditi PF, indicando: anno di inizio lavori, codice fiscale del beneficiario, importo della spesa, numero di rate. La dichiarazione va presentata ogni anno per tutta la durata della rateizzazione (10 anni per la maggior parte dei bonus). Conserva fatture e bonifici parlanti.',
 'renovation.faq.excessDeduction.q': 'Cosa succede se la detrazione annuale supera l\'IRPEF dovuta?',
 'renovation.faq.excessDeduction.a': 'La parte eccedente della detrazione annuale non può essere rimborsata né riportata agli anni successivi. Per questo è fondamentale avere sufficiente capienza fiscale ogni anno. Esempio: se la tua detrazione annuale è €2.400 ma la tua IRPEF lorda è solo €1.000, perdi €1.400 di detrazione per quell\'anno.',
 'renovation.faq.vecchioAccordo.q': 'Frontalieri vecchio accordo: possono usare questi bonus?',
 'renovation.faq.vecchioAccordo.a': 'Sì, ma con una condizione importante. I frontalieri assunti prima del 17/07/2023 ("vecchio accordo") non dichiarano il reddito svizzero in Italia, quindi la loro IRPEF da lavoro è zero. Possono comunque sfruttare i bonus se possiedono immobili con rendita catastale, percepiscono affitti, o hanno altri redditi italiani. Anche le imposte su immobili (IMU, cedolare secca) generano capienza. Conviene fare una simulazione con il commercialista.',

