 'tfr.badge': 'Calcolatore TFR / Liquidazione',
 'tfr.title': 'TFR e Liquidazione per Frontalieri: Svizzera vs Italia',
 'tfr.subtitle': 'In Svizzera non esiste il TFR. Scopri cosa lo sostituisce e confronta il 2° pilastro (LPP) con il TFR italiano su N anni di contributi.',
