 'relatedTools.jobs.title': 'Offerte di Lavoro {canton}',
 'relatedTools.jobs.desc': 'Cerca offerte di lavoro aggiornate per frontalieri in {canton}: banche, tech, farmaceutica e altro.',
 'tfr.noTfrTitle': 'In Svizzera il TFR non esiste!',
 'tfr.noTfrText': 'A differenza dell\'Italia, in Svizzera non è previsto il Trattamento di Fine Rapporto (TFR/liquidazione). Non viene accantonato nessun importo dal datore di lavoro alla cessazione del rapporto. Il concetto equivalente è il 2° pilastro (LPP/BVG): un risparmio obbligatorio per la previdenza professionale, gestito da casse pensioni e restituito come rendita o capitale al pensionamento.',
