 'tfr.tableLppTotal': 'LPP totale',
 'tfr.keyDifferencesTitle': 'Differenze chiave TFR vs LPP',
 'tfr.diffAccessTitle': 'Accesso ai fondi',
 'tfr.diffAccessTfr': 'Erogato alla fine del rapporto. Anticipo possibile (70%) per prima casa o spese mediche.',
 'tfr.diffAccessLpp': 'Disponibile al pensionamento (65 anni). Prelievo anticipato per abitazione primaria, avvio attività indipendente, o uscita definitiva dalla Svizzera.',
 'tfr.diffTaxTitle': 'Tassazione',
 'tfr.diffTaxTfr': 'Tassazione separata con aliquota media degli ultimi 5 anni. Generalmente favorevole.',
 'tfr.diffTaxLpp': 'Per frontalieri che rientrano in Italia: imposta alla fonte svizzera ridotta sul capitale, poi tassazione italiana al 5% (rendita) o separata (capitale).',
 'tfr.diffReturnTitle': 'Rendimento',
 'tfr.diffReturnTfr': 'Rivalutazione fissa: 1,5% + 75% inflazione ISTAT. Rendimento reale basso in periodi di bassa inflazione.',
 'tfr.diffReturnLpp': 'Tasso minimo BVG 1,25% (2026). Le casse pensioni migliori applicano fino al 3-4%. Il capitale è investito sui mercati finanziari.',
 'tfr.diffFrontaliereTitle': 'Cosa succede al frontaliere',
 'tfr.diffFrontaliereText1': 'Il frontaliere con Permesso G accumula LPP svizzero (2° pilastro). Quando lascia definitivamente la Svizzera, può richiedere il capitale della parte obbligatoria (prestazione di libero passaggio). La parte sovraobbligatoria va sulla polizza di libero passaggio.',
 'tfr.diffFrontaliereText2': 'Non perde il "TFR" perché il TFR non esiste in Svizzera — il 2° pilastro è il meccanismo equivalente, spesso con importi anche superiori al TFR italiano.',
 'tfr.faqTitle': 'Domande frequenti',
 'tfr.faq1Q': 'Perdo il TFR lavorando in Svizzera?',
 'tfr.faq1A': 'No, perché in Svizzera il TFR non esiste. Al suo posto c\'è il 2° pilastro (LPP/BVG), che è un meccanismo di previdenza professionale obbligatorio. I contributi sono accantonati presso la cassa pensione del datore di lavoro e ti saranno restituiti come rendita o capitale al pensionamento o quando lasci definitivamente la Svizzera.',
 'tfr.faq2Q': 'Posso recuperare il 2° pilastro se torno in Italia?',
 'tfr.faq2A': 'Sì. Se lasci definitivamente la Svizzera, puoi richiedere la liquidazione della parte obbligatoria del 2° pilastro. La parte sovraobbligatoria viene trasferita su un conto di libero passaggio. Se torni in un paese UE/AELS, la parte obbligatoria resta vincolata fino al pensionamento; la parte sovraobbligatoria può essere versata in contanti.',
 'tfr.faq3Q': 'Il 2° pilastro svizzero è più conveniente del TFR italiano?',
 'tfr.faq3A': 'Dipende dallo stipendio, dall\'età e dalla durata del rapporto. In generale, per stipendi medio-alti e lunghe carriere in Svizzera, il 2° pilastro accumula importi superiori al TFR italiano, poiché i contributi sono percentualmente più alti (7-18% vs 7,4% del TFR). Usa il simulatore sopra per il tuo caso specifico.',
 'tfr.faq4Q': 'Come viene calcolato il TFR italiano?',
 'tfr.faq4A': 'Il TFR italiano si calcola dividendo la RAL (Retribuzione Annua Lorda) per 13,5. L\'importo accantonato ogni anno viene rivalutato con la formula: 1,5% fisso + 75% dell\'inflazione ISTAT. Il TFR viene erogato alla cessazione del rapporto di lavoro (dimissioni, licenziamento, pensionamento).',
 'tfr.faq5Q': 'Come funziona il calcolo LPP per i frontalieri?',
 'tfr.faq5A': 'Il contributo LPP si calcola sul salario coordinato (stipendio lordo meno la deduzione di coordinamento di CHF 26.460, fino a un massimo di CHF 90.720). Il tasso varia con l\'età: 7% (25-34 anni), 10% (35-44), 15% (45-54), 18% (55-65). Il contributo è diviso equamente tra datore di lavoro e dipendente.',
 'tfr.relatedTitle': 'Strumenti correlati',
 'tfr.linkPension': 'Pianificatore Pensione',
 'tfr.linkPillar3': 'Simulatore 3° Pilastro',
 'tfr.linkPayslip': 'Simulatore Busta Paga',
 'tfr.disclaimer': 'I calcoli sono indicativi e basati sui parametri legali 2026 (tasso BVG 1,25%, deduzione di coordinamento CHF 26.460). Per il TFR si usa la formula legale (RAL/13,5 + rivalutazione). I risultati non costituiscono consulenza finanziaria o previdenziale. Consulta un esperto per la tua situazione specifica.',

